using NUnit.Framework;using UnityEditor.SceneManagement;using UnityEngine;
namespace Ssalddel.Unity.Experiments.CityFarmWorldIntegration.Editor.Tests{public sealed class PotatoHubReceivingLifecycleTests{private PotatoHubReceivingLifecyclePresenter p=null!;[SetUp]public void Open(){EditorSceneManager.OpenScene(PotatoHubReceivingLifecycleBuilder.ScenePath,OpenSceneMode.Single);p=GameObject.Find("WorldBootstrap/"+PotatoHubReceivingLifecycleBuilder.RootName).GetComponent<PotatoHubReceivingLifecyclePresenter>();p.ResetLifecycle();}[Test]public void HUB1_View는7개Action과도착경계를보존한다(){PotatoHubReceivingLifecycleBuilder.ValidateOpenScene();var root=GameObject.Find("WorldBootstrap/"+PotatoHubReceivingLifecycleBuilder.RootName);Assert.That(root.GetComponentsInChildren<PotatoHubReceivingActionButton>(true),Has.Length.EqualTo(7));Assert.That(p.CurrentModel.StateCode,Is.EqualTo("ArrivedAtHub"));}[Test]public void ReceivingPreviewConfirm은Tick전상태를바꾸지않는다(){var r=p.CurrentSnapshot.DataRevision;p.ReviewReceiving();p.ConfirmPreview();Assert.That(p.CurrentSnapshot.DataRevision,Is.EqualTo(r));Assert.That(p.CurrentSnapshot.InspectionResult,Is.Null);}[Test]public void InspectionTick은288kg합격12kg손실을표시한다(){p.FinishInspection();Assert.That(p.CurrentModel.StateCode,Is.EqualTo("Accepted"));Assert.That(p.CurrentModel.InspectionText,Does.Contain("accepted 288kg"));Assert.That(p.CurrentModel.InspectionText,Does.Contain("rejected 12kg"));}[Test]public void GoldenPath는합격손실Marker와동일Cargo를보존한다(){var cargo=p.CurrentSnapshot.Cargo.StableId;p.RunGoldenPath();var root=GameObject.Find("WorldBootstrap/"+PotatoHubReceivingLifecycleBuilder.RootName);Assert.That(root.transform.Find("AcceptedQuantityMarker_288kg").gameObject.activeSelf,Is.True);Assert.That(root.transform.Find("RejectedQuantityMarker_12kg").gameObject.activeSelf,Is.True);Assert.That(p.CurrentSnapshot.Cargo.StableId,Is.EqualTo(cargo));}}}
